#!/bin/bash
# Recreate the lib-assoc-array package skeleton: byte-identical upstream
# copies only.  Stub headers (linux/{types,compiler,kernel,bug,err,
# errno,slab,rcupdate}.h), wrappers.c, selftest.c and rust/ are
# maintained in the package, not generated by this script.
set -e
cd /mnt/c/Users/dev/Documents/GitHub/linux-rust/ports
mkdir -p lib-assoc-array/linux lib-assoc-array/rust
L=/mnt/c/Users/dev/Documents/GitHub/linux
cp "$L/lib/assoc_array.c" lib-assoc-array/assoc_array.c
cp "$L/include/linux/assoc_array.h" lib-assoc-array/linux/assoc_array.h
cp "$L/include/linux/assoc_array_priv.h" lib-assoc-array/linux/assoc_array_priv.h
ls -la lib-assoc-array lib-assoc-array/linux
